uint64_t Client(Broker& b,const char* name){HIGGS_HandClientInfo info{};info.structSize=sizeof(info);std::memcpy(info.name,name,std::strlen(name)+1);uint64_t c=0;CHECK(!b.Register(info,c));return c;}
void Hands(Broker& b){std::array<HIGGS_HandRecord,2> hands{};for(unsigned i=0;i<2;++i){auto& h=hands[i];h.physicalHand=i+1;h.observationMask=15;h.palmRotation[0]=h.palmRotation[4]=h.palmRotation[8]=1;}b.Publish(hands,1000);}
HIGGS_HandPartSources Frame(Broker& b,uint64_t sample,uint64_t at=1000,unsigned hand=1){HIGGS_HandPartSources f{};f.structSize=sizeof(f);f.physicalHand=hand;f.sourceCount=17;f.epoch=b.Epoch();f.sampleId=sample;f.observedAtNs=at;f.modelGeneration=1;f.handGeneration=b.HandGeneration(hand);f.trackingGeneration=1;f.trackingObservationId=sample;f.trackedAtNs=at;for(unsigned i=0;i<17;++i){auto& s=f.sources[i];s.sourceId=i;s.flags=1;s.modelScale=2;s.rotation[0]=s.rotation[4]=s.rotation[8]=1;s.position[0]=float(i);}return f;}
HIGGS_HandPartSetRequest Request(const HIGGS_HandPartSources& f){HIGGS_HandPartSetRequest r{};r.structSize=sizeof(r);r.physicalHand=f.physicalHand;r.partCount=4;r.durationMs=1000;r.epoch=f.epoch;r.sampleId=f.sampleId;r.modelGeneration=f.modelGeneration;for(unsigned i=0;i<4;++i){auto& d=r.parts[i];d.partId=i+10;d.shape=1;d.sourceId=i;d.localRotation[0]=d.localRotation[4]=d.localRotation[8]=1;for(float& h:d.halfExtentsMetres)h=.01f;}return r;}
struct Driver {HandPartService* service=nullptr;uint64_t client=0,generation=100;unsigned apply=0,cleanup=0;bool pendingCleanup=false,pending=false;};
HIGGS_HandStatus Apply(const HIGGS_HandPartSetRequest& r,const HIGGS_HandPartSources& f,HIGGS_HandPartSetState& s,bool cleanup,void* p){auto& d=*static_cast<Driver*>(p);CHECK(d.service->Capabilities()==31);HIGGS_HandPartSources copied{};if(!cleanup)CHECK(!d.service->Sources(d.client,1,copied,f.observedAtNs));if(cleanup){++d.cleanup;return d.pendingCleanup?HIGGS_HAND_PENDING:HIGGS_HAND_OK;}++d.apply;if(d.pending)return HIGGS_HAND_PENDING;s.bodyCount=r.partCount;for(unsigned i=0;i<r.partCount;++i){auto& b=s.bodies[i];b={};b.partId=r.parts[i].partId;b.bodyKey=i+9;b.bodyGeneration=d.generation+i;b.flags=15;CHECK(HandPartTarget(f,r.parts[i],b.targetPosition,b.targetRotation));b.rotation[0]=b.rotation[4]=b.rotation[8]=1;}return HIGGS_HAND_OK;}
