    CHECK(!s.Set(c,r,out,1000)&&out.stage==HIGGS_PART_PENDING&&out.requestRevision==1&&!out.appliedRevision);const auto id=out.setId;CHECK(s.Set(other,r,out,1000)==HIGGS_HAND_CONFLICT);driver.pending=true;s.Drain(1001);CHECK(!s.Copy(c,id,out)&&out.stage==HIGGS_PART_PENDING&&!out.appliedRevision);driver.pending=false;s.Drain(1002);CHECK(!s.Copy(c,id,out)&&out.stage==HIGGS_PART_ACTIVE&&out.appliedRevision==1&&out.bodyCount==4&&out.bodies[2].bodyGeneration==102);HIGGS_HandPartAttribution attr{};CHECK(!s.Resolve(other,f.epoch,11,102,attr)&&attr.partId==12&&attr.setId==id&&attr.owner==c);CHECK(s.Resolve(other,f.epoch,11,999,attr)==HIGGS_HAND_NOT_FOUND);CHECK(s.Resolve(other,f.epoch,11,0,attr)==HIGGS_HAND_INVALID_ARGUMENT);CHECK(s.Copy(other,id,out)==HIGGS_HAND_WRONG_OWNER);CHECK(s.End(other,id,f.epoch)==HIGGS_HAND_WRONG_OWNER);
    r.setId=id;r.expectedRevision=1;r.parts[0].localPosition[0]=50;CHECK(!s.Set(c,r,out,1003)&&out.requestRevision==2&&out.appliedRevision==1);CHECK(s.Set(c,r,out,1003)==HIGGS_HAND_STALE);r.expectedRevision=2;s.Drain(1004);CHECK(!s.Copy(c,id,out)&&out.appliedRevision==2&&out.bodies[0].targetPosition[0]==50&&out.bodies[0].position[0]==0);
    HIGGS_HandPartContact contact{};contact.structSize=sizeof(contact);contact.contactSequence=77;contact.part=attr;CHECK(s.Contact(contact));CHECK(!s.Contact(contact));HIGGS_HandPartContact old{};CHECK(!s.CopyContact(other,f.epoch,77,old)&&old.part.bodyGeneration==102);driver.pendingCleanup=true;CHECK(!s.End(c,id,f.epoch));s.Drain(1005);CHECK(!s.Copy(c,id,out)&&out.stage==HIGGS_PART_ENDING&&out.bodyCount==4);driver.pendingCleanup=false;s.Drain(1006);CHECK(!s.Copy(c,id,out)&&out.stage==HIGGS_PART_RELEASED&&!out.bodyCount);CHECK(s.Resolve(other,f.epoch,11,102,attr)==HIGGS_HAND_NOT_FOUND);CHECK(!s.CopyContact(other,f.epoch,77,old)&&old.part.bodyGeneration==102);
    // Same observed Havok UID is not the same body lifetime, including history.
    r=Request(f);driver.generation=200;CHECK(!s.Set(c,r,out,1007));s.Drain(1008);CHECK(!s.Copy(c,out.setId,out)&&out.bodies[2].bodyGeneration==202);CHECK(!s.CopyContact(other,f.epoch,77,old)&&old.part.bodyGeneration==102);CHECK(s.Resolve(other,f.epoch,11,102,attr)==HIGGS_HAND_NOT_FOUND);CHECK(!s.Resolve(other,f.epoch,11,202,attr));
    for(unsigned i=0;i<520;++i){contact.contactSequence=1000+i;contact.part=attr;CHECK(s.Contact(contact));}CHECK(s.CopyContact(other,f.epoch,77,old)==HIGGS_HAND_NOT_FOUND);CHECK(!s.CopyContact(other,f.epoch,1519,old));s.Drain(100001001);s.Drain(100001002);CHECK(!s.Copy(c,out.setId,out)&&out.stage==HIGGS_PART_BROKEN&&out.reason==HIGGS_PART_REASON_TRACKING);
    f=Frame(b,2,200000000);CHECK(s.Publish(f));r=Request(f);CHECK(!s.Set(c,r,out,f.observedAtNs));s.Drain(f.observedAtNs+1);auto model=f;model.sampleId=3;model.modelGeneration=2;model.observedAtNs++;CHECK(s.Publish(model));s.Drain(model.observedAtNs);s.Drain(model.observedAtNs);CHECK(!s.Copy(c,out.setId,out)&&out.stage==HIGGS_PART_BROKEN&&out.reason==HIGGS_PART_REASON_MODEL);
    f=model;r=Request(f);CHECK(!s.Set(c,r,out,f.observedAtNs));s.Drain(f.observedAtNs);CHECK(!b.Unregister(c));s.Drain(f.observedAtNs);CHECK(driver.cleanup>=5);b.ObserveWorld(2,false,300000000);Hands(b);CHECK(s.CopyContact(other,f.epoch,1519,old)==HIGGS_HAND_STALE);CHECK(!s.Contact(contact));
