void Api(){HIGGS_HandPartsInterface api{};CHECK(!HIGGS_QueryHandPartsInterface(1,sizeof(api),&api)&&api.structSize==sizeof(api)&&api.abiVersion==1);auto old=api;CHECK(HIGGS_QueryHandPartsInterface(2,sizeof(api),&api)==HIGGS_HAND_UNSUPPORTED_VERSION&&!std::memcmp(&old,&api,sizeof(api)));CHECK(HIGGS_QueryHandPartsInterface(1,sizeof(api)-1,&api)==HIGGS_HAND_BUFFER_TOO_SMALL);CHECK(api.CopySources(1,1,nullptr)==HIGGS_HAND_INVALID_ARGUMENT);HIGGS_HandPartSources f{};CHECK(api.CopySources(1,1,&f)==HIGGS_HAND_BUFFER_TOO_SMALL&&f.structSize==sizeof(f));CHECK(api.CopySources(UINT64_MAX,1,&f)==HIGGS_HAND_INVALID_CLIENT);HIGGS_HandPartSetState s{};s.structSize=sizeof(s);CHECK(api.SetParts(1,nullptr,&s)==HIGGS_HAND_INVALID_ARGUMENT);CHECK(api.CopyParts(UINT64_MAX,1,&s)==HIGGS_HAND_INVALID_CLIENT);HIGGS_HandPartAttribution a{};a.structSize=sizeof(a);CHECK(api.ResolveBody(UINT64_MAX,1,1,1,&a)==HIGGS_HAND_INVALID_CLIENT);}
